[metadata] {"type": "create", "filePath": "/app/covid19-response-infographic.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>COVID-19 Emergency Response - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body { width: 100%; height: 100%; background: #f0f4f8; }
    #container { width: 100%; height: 100%; }
    #export-btn {
      position: fixed; top: 16px; right: 16px; z-index: 999;
      background: #0067C5; color: white; border: none;
      padding: 10px 20px; border-radius: 6px; cursor: pointer;
      font-size: 14px; font-family: sans-serif;
    }
    #export-btn:hover { background: #0052a3; }
  </style>
</head>
<body>
<button id="export-btn" onclick="exportSVG()">Export SVG</button>
<div id="container"></div>
<script src="/app/vendor/infographic.min.js"></script>
<script>
const syntax = `infographic sequence-roadmap-vertical-simple
data
  title COVID-19 Emergency Response: From Detection to Recovery
  desc WHO-guided structured process coordinating 194 Member States across 6 regions — from first signal to long-term resilience
  sequences
    - label Phase 1: Surveillance & Early Detection
      desc National labs report respiratory clusters via IHR framework · WHO Disease Outbreak News issued · First bulletin: 5 Jan 2020
      icon eye
    - label Phase 2: Risk Assessment & Alert
      desc Rapid risk assessments evaluate spread likelihood & health system capacity · Situation Reports published · PHEIC declared 30 Jan 2020
      icon bell
    - label Phase 3: Response Operations & Clinical Management
      desc 5 pillars mobilized: IPC · Clinical Care · Health Workforce · Supply Chain · R&D · Partners: UNICEF, World Bank, MSF · 200+ guidance docs
      icon shield check
    - label Phase 4: Public Health & Social Measures
      desc Testing & contact tracing · Quarantine guidelines · Vaccination: ~1.9B COVAX doses to 146 countries · Multilingual risk communication
      icon people
    - label Phase 5: Recovery & Health System Resilience
      desc Restore routine services · Update national action plans · Address Long COVID & mental health · After-action reviews · Dashboard: millions of data points daily
      icon heart
theme
  palette #0067C5 #0091D5 #00BCD4 #F59E0B #10B981`;

const infographic = new AntVInfographic.Infographic({
  container: '#container',
  width: '100%',
  height: '100%',
});

infographic.render(syntax);

document.fonts?.ready.then(() => {
  infographic.render(syntax);
}).catch((error) => console.error('Error waiting for fonts:', error));

async function exportSVG() {
  try {
    const svgDataUrl = await infographic.toDataURL({ type: 'svg' });
    const a = document.createElement('a');
    a.href = svgDataUrl;
    a.download = 'covid19-response-infographic.svg';
    a.click();
  } catch(e) {
    console.error('Export failed:', e);
    alert('Export failed: ' + e.message);
  }
}
</script>
</body>
</html>
